def _cf_auth(
    token=None, # API token; defaults to `CLOUDFLARE_API_TOKEN` when `api_key` and `email` aren't given
    account_id=None, # Cloudflare account ID; defaults to `CLOUDFLARE_ACCOUNT_ID`
    email=None, # Account email for a global API key; defaults to `CLOUDFLARE_EMAIL`
    api_key=None, # Global API key; defaults to `CLOUDFLARE_API_KEY` when no token is given or set
):
    "Resolve Cloudflare auth headers and `account_id` from arguments and `CLOUDFLARE_*` env vars."
    account_id = account_id or os.getenv('CLOUDFLARE_ACCOUNT_ID')
    if not token:
        if api_key or email:
            api_key = api_key or os.getenv('CLOUDFLARE_API_KEY')
            email = email or os.getenv('CLOUDFLARE_EMAIL')
        elif t := os.getenv('CLOUDFLARE_API_TOKEN'): token = t
        elif k := os.getenv('CLOUDFLARE_API_KEY'): api_key, email = k, os.getenv('CLOUDFLARE_EMAIL')
    hdrs = ({'X-Auth-Email': email, 'X-Auth-Key': api_key} if api_key else {'Authorization': f'Bearer {token}'}) | {'Content-Type': 'application/json'}
    return hdrs, account_id, token, email, api_key

class CloudflareApi:
    "Cloudflare API client supporting user tokens, account tokens, and global API keys"
    def __init__(self,
        token=None, # API token; defaults to `CLOUDFLARE_API_TOKEN` when `api_key` and `email` aren't given
        account_id=None, # Account ID; defaults to `CLOUDFLARE_ACCOUNT_ID`
        email=None, # Account email for a global API key; defaults to `CLOUDFLARE_EMAIL`
        api_key=None, # Global API key; defaults to `CLOUDFLARE_API_KEY` when no token is given or set
        account_token:bool=False, # Is `token` an account-owned token (uses `/accounts/{account_id}/tokens/verify`)?
    ):
        hdrs, account_id, token, email, api_key = _cf_auth(token, account_id, email, api_key)
        store_attr()
        self.cli = OpenAPIClient(_cf_spec(), headers=hdrs, timeout=60.0)
        self.groups = self.cli.groups

    async def verify(self):
        "Check credentials via `/user` (global API key), account token verify (`account_token=True`), or user token verify."
        if self.api_key: return await self.user.get()
        if self.account_token: return await self.accounts.tokens.verify.get(account_id=self.account_id)
        return await self.user.tokens.verify.get()

    def __dir__(self): return super().__dir__() + list(self.groups)
    def _repr_markdown_(self): return "\n".join(f"- {o}" for o in sorted(self.groups))
    def __getattr__(self, k): return self.groups[k] if 'groups' in vars(self) and k in self.groups else stop(AttributeError(k))

