@patch
async def create_token(
    self:CloudflareApi,
    doms, # Domain names the token may act on
    perm_names, # Permission-group names, such as 'Zone Read' or 'DNS Write'. Names that don't match are skipped
    name, # Name for the new token
    grp='account.zone.', # Resource prefix after `com.cloudflare.api.`
    account_token:bool=False, # Create an account-owned token (nests zone resources under `account_id`)?
    account_id:str=None, # Account ID for account-owned tokens; defaults to `self.account_id`
):
    "Create a user or account-owned API token limited to `doms`. The token's value is shown only in this response."
    pref = 'com.cloudflare.api.'+grp
    acct = account_id or self.account_id
    tok_api = self.accounts.tokens if account_token else self.user.tokens
    pgs = (await (tok_api.permission_groups.get(acct) if account_token else tok_api.permission_groups.get())).result
    perms = [dict(id=p.id) for p in pgs if p.name in perm_names]
    zids = {f'{pref}{(await self.zones.list(name=d)).result[0].id}':'*' for d in doms}
    resources = {f'com.cloudflare.api.account.{acct}': zids} if account_token else zids
    pol = [dict(effect='allow', resources=resources, permission_groups=perms)]
    return await (tok_api.post(acct, name=name, policies=pol) if account_token else tok_api.post(name=name, policies=pol))

