@patch
async def create_r2_token(
    self:CloudflareApi,
    name:str, # Name for the new R2 token
    buckets=None, # Bucket name or iterable of bucket names; None grants account-wide R2 access
    write:bool=True, # Grant read/write access (False for read-only)
    account_id:str=None, # Account ID; defaults to `self.account_id`
    account_token:bool=True, # Create an account-owned service token (False for a user-owned token)
    jurisdiction:str='default', # R2 jurisdiction for bucket-scoped resources (`'default'`, `'eu'`, `'fedramp'`)
    expires_on:str=None, # Optional RFC3339 expiration timestamp
) -> AttrDict:
    "Create a Cloudflare R2 API token and return both the API response (`token`) and derived S3 credentials (`s3`)."
    acct = account_id or self.account_id
    if not acct: raise ValueError('account_id is required (pass it or set CLOUDFLARE_ACCOUNT_ID)')
    if isinstance(buckets, str): buckets = [buckets]
    if buckets:
        perm = 'Workers R2 Storage Bucket Item Write' if write else 'Workers R2 Storage Bucket Item Read'
        resources = {f'com.cloudflare.edge.r2.bucket.{acct}_{jurisdiction}_{b}': '*' for b in buckets}
    else:
        perm = 'Workers R2 Storage Write' if write else 'Workers R2 Storage Read'
        resources = {f'com.cloudflare.api.account.{acct}': '*'}
    tok_api = self.accounts.tokens if account_token else self.user.tokens
    pgs = (await (tok_api.permission_groups.get(acct) if account_token else tok_api.permission_groups.get())).result
    perms = [dict(id=p.id) for p in pgs if p.name == perm]
    if not perms: raise ValueError(f'Permission group not found: {perm}')
    kw = dict(name=name, policies=[dict(effect='allow', resources=resources, permission_groups=perms)])
    if expires_on: kw['expires_on'] = expires_on
    res = await (tok_api.post(acct, **kw) if account_token else tok_api.post(**kw))
    return AttrDict(token=res, s3=r2_s3_creds(res.result.id, res.result.value, acct, jurisdiction))
